pageHeading('MAKE DIGI-KONEK YOURS','Settings','Manage your workspace, account security, and business preferences.');
$values=$prefs;
if($error && ($_POST['action']??'')==='save-settings'){
    $values=array_replace($prefs,$_POST);
    foreach(['notify_orders','notify_reviews','notify_verification','notify_stock'] as $key)$values[$key]=isset($_POST[$key]);
    $values['preferred_categories']=is_array($_POST['preferred_categories']??null)?$_POST['preferred_categories']:[];
}
